from pathlib import Path
p=Path('gamevui-save.js');s=p.read_text()
s=s.replace('var MONEY_KEYS = ["playermoney", "money", "softmoney", "coins", "coin", "gold", "cash", "softcurrency", "currency", "dollars", "dollar", "balance", "moneycount", "coincount", "totalmoney"];','var MONEY_KEYS = ["playermoney", "currentmoney", "currentcoins", "currentcoin", "currentgold", "money", "coins", "coin", "gold", "cash", "balance", "currency", "softcurrency", "softmoney"];')
s=s.replace('if (o && o.expectedUpdatedAt) state.expectedUpdatedAt = String(o.expectedUpdatedAt);','if (o && String(o.gid || "") === String(gid || "") && o.expectedUpdatedAt) state.expectedUpdatedAt = String(o.expectedUpdatedAt);')
s=s.replace('origSetItem(META_KEY, JSON.stringify({ expectedUpdatedAt: state.expectedUpdatedAt }));','origSetItem(META_KEY, JSON.stringify({ gid: gid, expectedUpdatedAt: state.expectedUpdatedAt }));')
s=s.replace('var protoSet = proto.setItem;\n\t\tvar protoRemove = proto.removeItem;','var protoSet = proto.setItem;\n\t\tvar protoGet = proto.getItem;\n\t\tvar protoRemove = proto.removeItem;')
s=s.replace('\t\tproto.removeItem = function (key) {','\t\tproto.getItem = function (key) {\n\t\t\tvar value = protoGet.call(this, key);\n\t\t\tif (this === localStorage && value != null && !skipStorageKey(key)) {\n\t\t\t\trememberLocalKey(key, value);\n\t\t\t\tif (debugSave) gvLog("GV_LS_READ", String(key));\n\t\t\t}\n\t\t\treturn value;\n\t\t};\n\t\tproto.removeItem = function (key) {')
s=s.replace('state.seeding || state.idbBroken || state.pollBusy','state.seeding || state.pollBusy')
s=s.replace('if (state.loopStarted || !state.cloudActive || state.idbBroken) return;','if (state.loopStarted || !state.cloudActive) return;')
s=s.replace('\t\tif (document.hidden) return;\n\t\tstate.pollBusy = true;','\t\tif (document.hidden) return;\n\t\tif (state.idbBroken) { if (state.dirty) flushSave(false); return; }\n\t\tstate.pollBusy = true;')
